variables.query:
{
  products {
    edges {
      node {
        id
        handle
        title
        productType
        vendor
        tags
        status
        isGiftCard
        updatedAt
        options(first: 3) {
          name
          position
          values
        }
        variants {
          edges {
            node {
              id
              sku
              price
              compareAtPrice
              barcode
              selectedOptions {
                name
                value
              }
              inventoryItem {
                id
                tracked
                requiresShipping
                measurement {
                  weight {
                    unit
                    value
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
